#!/usr/bin/env python3
"""Task-scoped helper: inventory the workspace and preview candidate data files
for the European economic performance data storytelling report."""
import os
import json
import sys

root = os.getcwd()
print("CWD:", root)

def safe_preview(path, limit_lines=12, limit_chars=600):
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            head = []
            for _ in range(limit_lines):
                line = fh.readline()
                if not line:
                    break
                head.append(line)
        text = "".join(head)
        return text[:limit_chars]
    except Exception as exc:  # pragma: no cover - diagnostic only
        return f"<preview failed: {exc}>"

text_ext = {".csv", ".tsv", ".txt", ".json", ".md", ".log", ".xml", ".html"}

for dirpath, dirnames, filenames in os.walk(root):
    # skip hidden / venv style directories for tidiness
    dirnames[:] = [d for d in dirnames if not d.startswith(".") and d not in ("__pycache__", "venv", ".venv")]
    for name in sorted(filenames):
        full = os.path.join(dirpath, name)
        try:
            size = os.path.getsize(full)
        except OSError:
            size = -1
        rel = os.path.relpath(full, root)
        print("-" * 70)
        print(f"FILE: {rel}  ({size} bytes)")
        ext = os.path.splitext(name)[1].lower()
        if ext in text_ext and size <= 5_000_000:
            print(safe_preview(full))
        elif ext in text_ext:
            print(f"(file larger than preview limit; ext={ext})")
        else:
            print(f"(non-text extension: {ext or '<none>'})")
print("-" * 70)
print("Inventory complete.")

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Task-local helper: discover European economic performance data in the
workspace, analyse the series it contains, and write a data-storytelling
markdown report (per the data-storytelling skill: hook, context, trend,
contrast, insight, recommendation, caveats)."""
import csv
import json
import math
import os
import re
import statistics
import sys
from datetime import datetime, timezone

BASE = os.path.abspath(os.getcwd())
OUT_ARG = sys.argv[1] if len(sys.argv) > 1 else "european_economic_performance_data_story.md"
SEARCH_ARG = sys.argv[2] if len(sys.argv) > 2 else "."
REPORT_PATH = OUT_ARG if os.path.isabs(OUT_ARG) else os.path.join(BASE, OUT_ARG)
SEARCH_ROOT = SEARCH_ARG if os.path.isabs(SEARCH_ARG) else os.path.join(BASE, SEARCH_ARG)

SKIP_DIRS = {".git", ".codex", "__pycache__", "node_modules", ".venv", "venv", ".idea", ".vscode", ".tox", ".pytest_cache", ".mypy_cache"}
SKIP_HEADERS = {"unit", "units", "flag", "flags", "obs_flag", "obs_flags", "freq", "frequency",
                "status", "note", "notes", "comments", "id", "obs_status", "indicator_code"}
PERCENT_FAMILIES = {"gdp_growth", "inflation", "unemployment", "employment", "deficit", "debt"}
FAMILY_LABEL = {
    "gdp": "Economic output (GDP)",
    "gdp_growth": "Real GDP growth",
    "inflation": "Inflation (prices)",
    "unemployment": "Unemployment",
    "employment": "Employment",
    "debt": "Government debt",
    "deficit": "Budget balance",
    "productivity": "Productivity",
    "investment": "Investment",
    "exports": "Exports",
    "imports": "Imports",
    "trade_balance": "Trade / current account",
    "other": "Other indicators",
}

EUROPEAN_ECONOMIES = {
    "germany", "france", "italy", "spain", "netherlands", "poland", "belgium", "sweden",
    "austria", "ireland", "denmark", "finland", "portugal", "greece", "czechia",
    "czech republic", "romania", "hungary", "bulgaria", "croatia", "slovakia", "slovenia",
    "lithuania", "latvia", "estonia", "luxembourg", "cyprus", "malta", "norway",
    "switzerland", "iceland", "united kingdom", "uk", "ukraine", "serbia", "albania",
    "bosnia and herzegovina", "bosnia", "north macedonia", "montenegro", "moldova",
    "turkey", "russia", "belarus", "kosovo",
}

SPARK = "▁▂▃▄▅▆▇█"


def parse_number(v):
    """Lenient parser for European numeric styles (thousands and decimal separators)."""
    if v is None:
        return None
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        try:
            f = float(v)
            return f if math.isfinite(f) else None
        except Exception:
            return None
    t = str(v).strip()
    t = t.replace("\u00a0", " ").replace(" ", "")
    t = t.replace("−", "-").replace("–", "-").replace("—", "-")
    for ch in "€$£¥‚%":
        t = t.replace(ch, "")
    t = t.replace('"', "").replace("'", "").strip()
    low = t.lower()
    if t in ("", "-", ":", "..") or low in ("n/a", "na", "nan", "null", "none", "n.a."):
        return None
    if not re.search(r"\d", t):
        return None
    m = re.fullmatch(r"\((.+)\)", t)
    if m:
        t = "-" + m.group(1)
    has_comma = "," in t
    has_dot = "." in t
    if has_comma and has_dot:
        if t.rfind(",") > t.rfind("."):
            t = t.replace(".", "").replace(",", ".")
        else:
            t = t.replace(",", "")
    elif has_comma:
        if re.fullmatch(r"-?\d{1,3}(,\d{3})+", t):
            t = t.replace(",", "")
        else:
            t = t.replace(",", ".")
    else:
        if re.fullmatch(r"-?\d{1,3}(\.\d{3})+", t):
            t = t.replace(".", "")
    try:
        f = float(t)
        return f if math.isfinite(f) else None
    except Exception:
        return None


def year_of(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        try:
            y = int(float(v))
        except Exception:
            return None
        return y if 1950 <= y <= 2100 else None
    s = str(v).strip()
    m = re.search(r"(19[5-9]\d|20[0-2]\d)", s)
    return int(m.group(1)) if m else None


def clean_header(h):
    if h is None:
        return ""
    return str(h).strip().strip('"').strip("'").strip()


def classify(name):
    n = " " + str(name).lower() + " "
    if "unemploy" in n:
        return "unemployment"
    if "inflation" in n or " hicp" in n or " cpi" in n or "consumer price" in n or "harmonised index" in n:
        return "inflation"
    if "government debt" in n or "public debt" in n or "gross debt" in n or "debt-to-gdp" in n:
        return "debt"
    if "deficit" in n or "budget balance" in n or "fiscal balance" in n or "net lending" in n:
        return "deficit"
    if "employment" in n or "employment rate" in n:
        return "employment"
    if "product" in n:
        return "productivity"
    if "investment" in n or "invest" in n:
        return "investment"
    if "export" in n and "import" not in n:
        return "exports"
    if "import" in n and "export" not in n:
        return "imports"
    if "trade balance" in n or "current account" in n or "net trade" in n:
        return "trade_balance"
    if "gdp" in n or "gross domestic" in n or "gross value added" in n:
        if "growth" in n or "change" in n or "expansion" in n:
            return "gdp_growth"
        return "gdp"
    if "growth" in n or "expansion" in n or "yoy" in n or "year-over-year" in n or "year on year" in n or "annual change" in n or "rate of change" in n:
        return "gdp_growth"
    return "other"


def is_aggregate_entity(name):
    if not name:
        return False
    n = str(name).strip().lower()
    if n in ("eu", "eu27", "eu28", "eu-27", "eu-28", "euro area", "eurozone", "europe",
             "european union", "european union (27)", "european union - 27 countries",
             "european union – 27 countries", "european economic area", "eea", "efta",
             "ea", "ea19", "ea20", "total", "average", "all countries", "world"):
        return True
    if n.startswith("eu2") or n.startswith("eu-2") or n.startswith("eu ") or n.startswith("ea1") or n.startswith("ea2"):
        return True
    if n.startswith("euro area") or n.startswith("european union") or n.startswith("eurozone"):
        return True
    if "all countr" in n or "aggregate" in n:
        return True
    return False


def norm_pts(pts):
    """Keep points with numbers; sort chronologically and de-duplicate years."""
    clean = [(y, v) for (y, v) in pts if v is not None and parse_number(v) is not None]
    if not clean:
        return []
    clean = [(y, float(v)) for (y, v) in clean]
    yd = {}
    for y, v in clean:
        if isinstance(y, int):
            yd.setdefault(y, []).append(v)
    if yd and sum(len(x) for x in yd.values()) == len(clean):
        return sorted((y, statistics.mean(vs)) for y, vs in yd.items())
    ints = sorted((y, v) for y, v in clean if isinstance(y, int))
    others = [(y, v) for y, v in clean if not isinstance(y, int)]
    return ints + others


def frac_numeric(values, cap=200):
    n = 0
    ok = 0
    for v in values[:cap]:
        if v is None:
            continue
        s = str(v).strip()
        if not s:
            continue
        n += 1
        if parse_number(s) is not None:
            ok += 1
    return (ok / n) if n else 0.0


def frac_years(values, cap=200):
    n = 0
    ok = 0
    for v in values[:cap]:
        if v is None:
            continue
        s = str(v).strip()
        if not s:
            continue
        n += 1
        if year_of(s) is not None:
            ok += 1
    return (ok / n) if n else 0.0


def frac_strings(values, cap=200):
    n = 0
    ok = 0
    for v in values[:cap]:
        if v is None:
            continue
        s = str(v).strip()
        if not s:
            continue
        n += 1
        if parse_number(s) is None and year_of(s) is None:
            ok += 1
    return (ok / n) if n else 0.0


def header_year_token(h):
    m = re.fullmatch(r"\s*(19[5-9]\d|20[0-2]\d)\s*", str(h))
    return int(m.group(1)) if m else None


YEAR_HEADER_NAMES = {"year", "years", "time", "period", "date", "observation time", "time period", "ref period", "reporting year"}


def col_values(rows, c):
    return [r[c] if c < len(r) else None for r in rows]


def load_tables(path):
    """Return list of tables: {'headers': [..] or None, 'rows': [[..]], 'source': name}."""
    ext = os.path.splitext(path)[1].lower()
    src = os.path.basename(path)
    if ext == ".json":
        with open(path, "r", encoding="utf-8-sig", errors="replace") as fh:
            data = json.load(fh)
        tables = []
        if isinstance(data, dict):
            first = next(iter(data.values()), None)
            if isinstance(first, list) and first and all(isinstance(x, (int, float)) for x in first):
                # dict of parallel arrays
                keys = list(data.keys())
                n = len(first)
                rows = []
                for i in range(n):
                    rows.append([data[k][i] if isinstance(data[k], list) and i < len(data[k]) else data[k] for k in keys])
                tables.append({"headers": keys, "rows": rows, "source": src})
            elif isinstance(first, dict):
                rows = []
                for ent, sub in data.items():
                    if isinstance(sub, dict):
                        for y, v in sub.items():
                            rows.append([ent, y, v])
                    else:
                        rows.append([ent, sub])
                tables.append({"headers": ["entity", "year", "value"], "rows": rows, "source": src})
            else:
                tables.append({"headers": list(data.keys()), "rows": [list(data.values())], "source": src})
        elif isinstance(data, list):
            if data and isinstance(data[0], dict):
                headers = list(data[0].keys())
                rows = [[r.get(h) for h in headers] for r in data]
                tables.append({"headers": headers, "rows": rows, "source": src})
            elif data and isinstance(data[0], list):
                tables.append({"headers": None, "rows": data, "source": src})
        return tables

    # text based (csv / tsv / dat / md / txt)
    with open(path, "r", encoding="utf-8-sig", errors="replace") as fh:
        text = fh.read()
    lines = text.splitlines()
    tables = []
    if ext in (".md", ".markdown"):
        blocks = []
        cur = []
        for ln in lines:
            if "|" in ln:
                cur.append(ln)
            else:
                if len(cur) >= 2:
                    blocks.append(cur)
                cur = []
        if len(cur) >= 2:
            blocks.append(cur)
        for block in blocks:
            rows = []
            for ln in block:
                if re.fullmatch(r"\s*\|?[\s:\-|]+\|?\s*", ln) and "-" in ln:
                    continue
                cells = [c.strip() for c in ln.strip().strip("|").split("|")]
                rows.append(cells)
            if len(rows) >= 2:
                tables.append({"headers": rows[0], "rows": rows[1:], "source": src})
        return tables

    # candidate delimiters
    sample = "\n".join(lines[:6])
    delim = None
    best = 0
    for d in [",", ";", "\t", "|"]:
        cnt = sample.count(d)
        if cnt > best:
            best = cnt
            delim = d
    if delim is None or best == 0:
        return []
    parsed = list(csv.reader(lines, delimiter=delim))
    parsed = [r for r in parsed if any(str(c).strip() for c in r)]
    if len(parsed) < 2:
        return []
    # first row as header if it is mostly non-numeric
    first = [clean_header(c) for c in parsed[0]]
    fn = frac_numeric(first)
    if fn < 0.5:
        headers = first
        rows = parsed[1:]
    else:
        headers = None
        rows = parsed
    tables.append({"headers": headers, "rows": rows, "source": src})
    return tables


def process_table(t, out, src_label=None, n_files_parsed=None):
    headers = t.get("headers")
    rows = t.get("rows") or []
    if not rows:
        return
    if headers is None:
        if rows and any(parse_number(c) is None and year_of(c) is None for c in rows[0]) and len(rows) > 1:
            headers = [clean_header(c) for c in rows[0]]
            rows = rows[1:]
        else:
            ncol = max(len(r) for r in rows)
            headers = [f"col_{i}" for i in range(ncol)]
    headers = [clean_header(h) for h in headers]
    maxcols = max(len(headers), max((len(r) for r in rows), default=0))
    while len(headers) < maxcols:
        headers.append(f"col_{len(headers)}")
    rows = [list(r) + [None] * (maxcols - len(r)) for r in rows]

    ncols = len(headers)
    # -- characterise columns -------------------------------------------------
    header_years = [header_year_token(h) for h in headers]
    yfracs = []
    nfracs = []
    sfracs = []
    uniq = []
    for c in range(ncols):
        vals = col_values(rows, c)
        yfracs.append(frac_years(vals))
        nfracs.append(frac_numeric(vals))
        sfracs.append(frac_strings(vals))
        uv = set()
        for v in vals:
            s = str(v).strip() if v is not None else ""
            if s:
                uv.add(s.lower())
        uniq.append(len(uv))

    # -- matrix orientation (years as column headers) --------------------------
    year_cols = [c for c in range(ncols) if header_years[c] is not None]
    if len(year_cols) >= 2:
        key_cols = [c for c in range(ncols) if c not in year_cols]
        ent = None
        ind = None
        for c in key_cols:
            hl = headers[c].lower()
            if not ent and (any(w in hl for w in ("countr", "geo", "econom", "member state", "region", "nation")) or (sfracs[c] > 0.6 and nfracs[c] < 0.4)):
                ent = c
            elif not ind and any(w in hl for w in ("indicator", "measure", "variable", "metric", "series", "statistic", "item")):
                ind = c
        metric_base = re.sub(r"[\s_]+", " ", os.path.splitext(t.get("source", ""))[0]).strip() or "value"
        for r in rows:
            metric = clean_header(r[ind]) if (ind is not None and r[ind] is not None) else metric_base
            entity = clean_header(r[ent]) if (ent is not None and r[ent] is not None) else None
            pts = []
            for c in year_cols:
                pts.append((header_years[c], parse_number(r[c])))
            if pts:
                out.append({"metric": metric, "entity": entity, "pts": pts, "src": t.get("source", "")})
        return

    # -- row orientation --------------------------------------------------------
    # explicit year column: header match first, else content match
    year_col = None
    for c in range(ncols):
        if headers[c].lower() in YEAR_HEADER_NAMES:
            year_col = c
            break
    if year_col is None:
        best_c, best_f = None, 0.0
        for c in range(ncols):
            if yfracs[c] > best_f:
                best_c, best_f = c, yfracs[c]
        if best_c is not None and best_f >= 0.6 and nfracs[best_c] < 0.8:
            year_col = best_c
    if year_col is not None:
        year_col = int(year_col)

    def is_skip(c):
        return headers[c].lower() in SKIP_HEADERS or headers[c].lower().startswith("obs_")

    key_frac = 0.45
    ind_col = None
    for c in range(ncols):
        if c == year_col or is_skip(c):
            continue
        if any(w in headers[c].lower() for w in ("indicator", "measure", "variable", "metric", "series", "statistic", "item", "component")):
            ind_col = c
            break
    ent_col = None
    if year_col is not None:
        for c in range(ncols):
            if c == year_col or c == ind_col or is_skip(c):
                continue
            if nfracs[c] > 0.5:
                continue
            if any(w in headers[c].lower() for w in ("countr", "geo", "region", "economy", "member state", "nation", "economies", "area")):
                ent_col = c
                break
        if ent_col is None:
            best_c, best_f = None, 0.0
            for c in range(ncols):
                if c == year_col or c == ind_col or is_skip(c):
                    continue
                if nfracs[c] > 0.5 or year_of(headers[c]) is not None:
                    continue
                score = sfracs[c]
                if headers[c].lower() in ("entity", "name", "label"):
                    score = 1.0
                if score > best_f:
                    best_c, best_f = c, score
            if best_c is not None and best_f >= key_frac and uniq[best_c] >= 2:
                ent_col = best_c

    val_col = None
    if ind_col is not None:
        for c in range(ncols):
            if c in (year_col, ind_col, ent_col) or is_skip(c):
                continue
            if headers[c].lower() in ("value", "values", "amount", "observation", "obs_value", "data"):
                val_col = c
                break
        if val_col is None:
            numeric_only = [c for c in range(ncols) if c not in (year_col, ind_col, ent_col) and not is_skip(c) and nfracs[c] >= 0.55 and header_years[c] is None]
            if len(numeric_only) == 1:
                val_col = numeric_only[0]

    numeric_cols = []
    for c in range(ncols):
        if c in (year_col, ind_col, ent_col, val_col) or is_skip(c):
            continue
        if header_years[c] is not None:
            continue
        if nfracs[c] >= 0.55 and sfracs[c] < 0.5:
            numeric_cols.append(c)

    metric_base = re.sub(r"[\s_]+", " ", os.path.splitext(t.get("source", ""))[0]).strip() or "value"

    if ind_col is not None and val_col is not None:
        for r in rows:
            metric = clean_header(r[ind_col]) if r[ind_col] is not None else metric_base
            entity = clean_header(r[ent_col]) if (ent_col is not None and r[ent_col] is not None) else None
            y = year_of(r[year_col]) if year_col is not None else None
            v = parse_number(r[val_col]) if val_col < len(r) else None
            if v is not None or y is not None:
                out.append({"metric": metric, "entity": entity, "pts": [(y, v)], "src": t.get("source", "")})
        return

    if numeric_cols:
        for c in numeric_cols:
            name = clean_header(headers[c]) or metric_base
            for r in rows:
                y = year_of(r[year_col]) if year_col is not None else None
                v = parse_number(r[c])
                if v is not None:
                    out.append({"metric": name, "entity": clean_header(r[ent_col]) if (ent_col is not None and r[ent_col] is not None) else None,
                                "pts": [(y, v)], "src": t.get("source", "")})
        return

    if ent_col is not None:
        name = metric_base
        for r in rows:
            v = parse_number(r[0]) if r and headers[0].lower() not in SKIP_HEADERS else None
            # fall back: pick the numeric cell
            if v is None:
                for c in range(ncols):
                    v = parse_number(r[c])
                    if v is not None:
                        break
            y = year_of(r[year_col]) if year_col is not None else None
            if v is not None:
                out.append({"metric": name, "entity": clean_header(r[ent_col]) if r[ent_col] is not None else None,
                            "pts": [(y, v)], "src": t.get("source", "")})
        return

    # single unnamed numeric series
    for c in range(ncols):
        if nfracs[c] > 0.4 and c != year_col:
            for r in rows:
                y = year_of(r[year_col]) if year_col is not None else None
                v = parse_number(r[c])
                if v is not None:
                    out.append({"metric": metric_base, "entity": None, "pts": [(y, v)], "src": t.get("source", "")})
            return


def discover_files(root):
    found = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS and not d.startswith(".")]
        for fn in sorted(filenames):
            full = os.path.join(dirpath, fn)
            if fn == os.path.basename(sys.argv[0]) or os.path.abspath(full) == os.path.abspath(REPORT_PATH):
                continue
            ext = os.path.splitext(fn)[1].lower()
            if ext in (".csv", ".tsv", ".txt", ".dat", ".json", ".md", ".markdown"):
                found.append(full)
    return found


def pick_series(recs):
    # merge records with identical (family, name-key, entity) and take the longest per (family, entity)
    merged = {}
    for rec in recs:
        key = (classify(rec["metric"]), str(rec["metric"]).lower(), (rec["entity"] or "").lower())
        pts = norm_pts(rec["pts"])
        if not pts:
            continue
        if key not in merged:
            merged[key] = {"family": classify(rec["metric"]), "name": rec["metric"],
                           "entity": rec["entity"], "src": rec["src"], "pts": pts}
        else:
            # merge same-name series points
            existing = merged[key]
            comb = existing["pts"] + pts
            merged[key]["pts"] = norm_pts(comb)
    by_fam_ent = {}
    for key, rec in merged.items():
        fam = rec["family"]
        ent = (rec["entity"] or "").lower()
        cur = by_fam_ent.get((fam, ent))
        if cur is None or len(rec["pts"]) > len(cur["pts"]):
            by_fam_ent[(fam, ent)] = rec
    return list(by_fam_ent.values())


def eu_series(series, family):
    """Europe-wide series: official aggregate if present, else simple average/aggregate of economies."""
    aggs = [s for s in series if s["family"] == family and is_aggregate_entity(s["entity"]) and len(s["pts"]) >= 2]
    if aggs:
        s = max(aggs, key=lambda x: len(x["pts"]))
        return s["pts"], s["name"] + " (aggregate)", s["src"]
    ents = [s for s in series if s["family"] == family and s["entity"] and not is_aggregate_entity(s["entity"]) and len(s["pts"]) >= 2]
    if len(ents) >= 3:
        years = sorted({y for s in ents for y, _ in s["pts"] if isinstance(y, int)})
        pts = []
        for y in years:
            vals = [v for s in ents for yy, v in s["pts"] if yy == y]
            if len(vals) >= max(2, int(0.4 * len(ents))):
                if family == "gdp":
                    pts.append((y, sum(vals)))
                else:
                    pts.append((y, statistics.mean(vals)))
        if pts:
            return pts, f"Europe simple average of {len(ents)} reporting economies", None
    return [], None, None


def fmt_num(v, pct=False, signed=False):
    if v is None:
        return "n/a"
    dp = 1
    if abs(v) < 1 and v != 0:
        dp = 2
    if abs(v) >= 1000 and not pct:
        s = f"{v:,.0f}"
    else:
        s = f"{v:.{dp}f}"
    if pct:
        s = s + "%"
    if signed and v > 0:
        s = "+" + s
    return s


def summary(pts):
    if not pts:
        return None
    n = len(pts)
    first_y, first_v = pts[0]
    last_y, last_v = pts[-1]
    prev_y, prev_v = pts[-2] if n >= 2 else (None, None)
    vals = [v for _, v in pts]
    net = last_v - first_v
    return {"n": n, "first_y": first_y, "first_v": first_v, "last_y": last_y, "last_v": last_v,
            "prev_y": prev_y, "prev_v": prev_v, "net": net, "min": min(vals), "max": max(vals),
            "min_y": pts[vals.index(min(vals))][0], "max_y": pts[vals.index(max(vals))][0]}


def spark(pts, width=10):
    pts = pts[-width:]
    vals = [v for _, v in pts]
    lo, hi = min(vals), max(vals)
    if hi - lo < 1e-12:
        return "▄" * len(vals)
    return "".join(SPARK[min(7, max(0, int(round((v - lo) / (hi - lo) * 7))))] for v in vals)


def bar(vals_dict, width=22):
    items = [(k, v) for k, v in vals_dict.items() if v is not None]
    if not items:
        return []
    mx = max(abs(v) for _, v in items) or 1.0
    lines = []
    for k, v in sorted(items, key=lambda kv: kv[1], reverse=True):
        ln = int(round(abs(v) / mx * width))
        arrow = "▲" if v > 0 else ("▼" if v < 0 else "•")
        lines.append((k, v, arrow, "█" * ln))
    return lines


def pearson(xs, ys):
    if len(xs) < 4 or len(xs) != len(ys):
        return None
    try:
        r = statistics.correlation(xs, ys)
        return r if math.isfinite(r) else None
    except Exception:
        return None


def latest_cross(series, family):
    rows = []
    for s in series:
        if s["family"] != family or not s["entity"] or is_aggregate_entity(s["entity"]):
            continue
        if len(s["pts"]) < 2:
            continue
        y, v = s["pts"][-1]
        prev = None
        if len(s["pts"]) >= 2:
            prev = s["pts"][-2][1]
        rows.append({"name": s["entity"], "last": v, "last_y": y, "prev": prev, "pts": s["pts"]})
    return rows


def trend_phrase(family, net):
    eps = 1e-9
    if abs(net) < eps:
        return "broadly flat"
    if family in ("gdp_growth", "gdp"):
        return "expanding" if net > 0 else "contracting"
    if family == "inflation":
        return "rising prices" if net > 0 else "disinflation"
    if family in ("unemployment",):
        return "tightening labour market (unemployment down)" if net < 0 else "softening labour market (unemployment up)"
    if family == "employment":
        return "more people in work" if net > 0 else "fewer people in work"
    if family == "deficit":
        return "improving fiscal balance" if net > 0 else "widening fiscal deficit"
    if family == "debt":
        return "deleveraging" if net < 0 else "rising debt"
    return "rising" if net > 0 else "falling"


# ----------------------------------------------------------------------------
def main():
    files = discover_files(SEARCH_ROOT)
    recs = []
    file_report = []
    for path in files:
        try:
            tables = load_tables(path)
        except Exception as exc:  # noqa: BLE001
            print(f"[warn] could not parse {path}: {exc}")
            continue
        nrows = 0
        for t in tables:
            nrows += len(t.get("rows") or [])
            process_table(t, recs)
        if tables:
            file_report.append({"file": os.path.relpath(path, BASE), "tables": len(tables), "rows": nrows})
    series = pick_series(recs)

    fams = sorted({s["family"] for s in series})
    ents = sorted({s["entity"] for s in series if s["entity"] and not is_aggregate_entity(s["entity"])})
    aggs = sorted({s["entity"] for s in series if s["entity"] and is_aggregate_entity(s["entity"])})
    years_all = [y for s in series for y, _ in s["pts"] if isinstance(y, int)]
    period = (min(years_all), max(years_all)) if years_all else (None, None)

    fam_order = ["gdp_growth", "inflation", "unemployment", "gdp", "debt", "deficit",
                 "employment", "productivity", "investment", "exports", "imports", "trade_balance"]
    fams_present = [f for f in fam_order if f in fams] + [f for f in sorted(fams) if f not in fam_order and f != "other"] + (["other"] if "other" in fams else [])

