def parse_number(v):
    """Lenient parser for European numeric styles (thousands and decimal separators)."""
    if v is None:
        return None
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        try:
            f = float(v)
            return f if math.isfinite(f) else None
        except Exception:
            return None
    t = str(v).strip()
    t = t.replace("\u00a0", " ").replace(" ", "")
    t = t.replace("−", "-").replace("–", "-").replace("—", "-")
    for ch in "€$£¥‚%":
        t = t.replace(ch, "")
    t = t.replace('"', "").replace("'", "").strip()
    low = t.lower()
    if t in ("", "-", ":", "..") or low in ("n/a", "na", "nan", "null", "none", "n.a."):
        return None
    if not re.search(r"\d", t):
        return None
    m = re.fullmatch(r"\((.+)\)", t)
    if m:
        t = "-" + m.group(1)
    has_comma = "," in t
    has_dot = "." in t
    if has_comma and has_dot:
        if t.rfind(",") > t.rfind("."):
            t = t.replace(".", "").replace(",", ".")
        else:
            t = t.replace(",", "")
    elif has_comma:
        if re.fullmatch(r"-?\d{1,3}(,\d{3})+", t):
            t = t.replace(",", "")
        else:
            t = t.replace(",", ".")
    else:
        if re.fullmatch(r"-?\d{1,3}(\.\d{3})+", t):
            t = t.replace(".", "")
    try:
        f = float(t)
        return f if math.isfinite(f) else None
    except Exception:
        return None


def year_of(v):
