def load_tables(path):
    """Return list of tables: {'headers': [..] or None, 'rows': [[..]], 'source': name}."""
    ext = os.path.splitext(path)[1].lower()
    src = os.path.basename(path)
    if ext == ".json":
        with open(path, "r", encoding="utf-8-sig", errors="replace") as fh:
            data = json.load(fh)
        tables = []
        if isinstance(data, dict):
            first = next(iter(data.values()), None)
            if isinstance(first, list) and first and all(isinstance(x, (int, float)) for x in first):
                # dict of parallel arrays
                keys = list(data.keys())
                n = len(first)
                rows = []
                for i in range(n):
                    rows.append([data[k][i] if isinstance(data[k], list) and i < len(data[k]) else data[k] for k in keys])
                tables.append({"headers": keys, "rows": rows, "source": src})
            elif isinstance(first, dict):
                rows = []
                for ent, sub in data.items():
                    if isinstance(sub, dict):
                        for y, v in sub.items():
                            rows.append([ent, y, v])
                    else:
                        rows.append([ent, sub])
                tables.append({"headers": ["entity", "year", "value"], "rows": rows, "source": src})
            else:
                tables.append({"headers": list(data.keys()), "rows": [list(data.values())], "source": src})
        elif isinstance(data, list):
            if data and isinstance(data[0], dict):
                headers = list(data[0].keys())
                rows = [[r.get(h) for h in headers] for r in data]
                tables.append({"headers": headers, "rows": rows, "source": src})
            elif data and isinstance(data[0], list):
                tables.append({"headers": None, "rows": data, "source": src})
        return tables

    # text based (csv / tsv / dat / md / txt)
    with open(path, "r", encoding="utf-8-sig", errors="replace") as fh:
        text = fh.read()
    lines = text.splitlines()
    tables = []
    if ext in (".md", ".markdown"):
        blocks = []
        cur = []
        for ln in lines:
            if "|" in ln:
                cur.append(ln)
            else:
                if len(cur) >= 2:
                    blocks.append(cur)
                cur = []
        if len(cur) >= 2:
            blocks.append(cur)
        for block in blocks:
            rows = []
            for ln in block:
                if re.fullmatch(r"\s*\|?[\s:\-|]+\|?\s*", ln) and "-" in ln:
                    continue
                cells = [c.strip() for c in ln.strip().strip("|").split("|")]
                rows.append(cells)
            if len(rows) >= 2:
                tables.append({"headers": rows[0], "rows": rows[1:], "source": src})
        return tables

    # candidate delimiters
    sample = "\n".join(lines[:6])
    delim = None
    best = 0
    for d in [",", ";", "\t", "|"]:
        cnt = sample.count(d)
        if cnt > best:
            best = cnt
            delim = d
    if delim is None or best == 0:
        return []
    parsed = list(csv.reader(lines, delimiter=delim))
    parsed = [r for r in parsed if any(str(c).strip() for c in r)]
    if len(parsed) < 2:
        return []
    # first row as header if it is mostly non-numeric
    first = [clean_header(c) for c in parsed[0]]
    fn = frac_numeric(first)
    if fn < 0.5:
        headers = first
        rows = parsed[1:]
    else:
        headers = None
        rows = parsed
    tables.append({"headers": headers, "rows": rows, "source": src})
    return tables


def process_table(t, out, src_label=None, n_files_parsed=None):
    headers = t.get("headers")
    rows = t.get("rows") or []
    if not rows:
        return
    if headers is None:
        if rows and any(parse_number(c) is None and year_of(c) is None for c in rows[0]) and len(rows) > 1:
            headers = [clean_header(c) for c in rows[0]]
            rows = rows[1:]
        else:
            ncol = max(len(r) for r in rows)
            headers = [f"col_{i}" for i in range(ncol)]
    headers = [clean_header(h) for h in headers]
    maxcols = max(len(headers), max((len(r) for r in rows), default=0))
    while len(headers) < maxcols:
        headers.append(f"col_{len(headers)}")
    rows = [list(r) + [None] * (maxcols - len(r)) for r in rows]

    ncols = len(headers)
    # -- characterise columns -------------------------------------------------
    header_years = [header_year_token(h) for h in headers]
    yfracs = []
    nfracs = []
    sfracs = []
    uniq = []
    for c in range(ncols):
        vals = col_values(rows, c)
        yfracs.append(frac_years(vals))
        nfracs.append(frac_numeric(vals))
        sfracs.append(frac_strings(vals))
        uv = set()
        for v in vals:
            s = str(v).strip() if v is not None else ""
            if s:
                uv.add(s.lower())
        uniq.append(len(uv))

    # -- matrix orientation (years as column headers) --------------------------
    year_cols = [c for c in range(ncols) if header_years[c] is not None]
    if len(year_cols) >= 2:
        key_cols = [c for c in range(ncols) if c not in year_cols]
        ent = None
        ind = None
        for c in key_cols:
            hl = headers[c].lower()
            if not ent and (any(w in hl for w in ("countr", "geo", "econom", "member state", "region", "nation")) or (sfracs[c] > 0.6 and nfracs[c] < 0.4)):
                ent = c
            elif not ind and any(w in hl for w in ("indicator", "measure", "variable", "metric", "series", "statistic", "item")):
                ind = c
        metric_base = re.sub(r"[\s_]+", " ", os.path.splitext(t.get("source", ""))[0]).strip() or "value"
        for r in rows:
            metric = clean_header(r[ind]) if (ind is not None and r[ind] is not None) else metric_base
            entity = clean_header(r[ent]) if (ent is not None and r[ent] is not None) else None
            pts = []
            for c in year_cols:
                pts.append((header_years[c], parse_number(r[c])))
            if pts:
                out.append({"metric": metric, "entity": entity, "pts": pts, "src": t.get("source", "")})
        return

    # -- row orientation --------------------------------------------------------
    # explicit year column: header match first, else content match
    year_col = None
    for c in range(ncols):
        if headers[c].lower() in YEAR_HEADER_NAMES:
            year_col = c
            break
    if year_col is None:
        best_c, best_f = None, 0.0
        for c in range(ncols):
            if yfracs[c] > best_f:
                best_c, best_f = c, yfracs[c]
        if best_c is not None and best_f >= 0.6 and nfracs[best_c] < 0.8:
            year_col = best_c
    if year_col is not None:
        year_col = int(year_col)

    def is_skip(c):
        return headers[c].lower() in SKIP_HEADERS or headers[c].lower().startswith("obs_")

    key_frac = 0.45
    ind_col = None
    for c in range(ncols):
        if c == year_col or is_skip(c):
            continue
        if any(w in headers[c].lower() for w in ("indicator", "measure", "variable", "metric", "series", "statistic", "item", "component")):
            ind_col = c
            break
    ent_col = None
    if year_col is not None:
        for c in range(ncols):
            if c == year_col or c == ind_col or is_skip(c):
                continue
            if nfracs[c] > 0.5:
                continue
            if any(w in headers[c].lower() for w in ("countr", "geo", "region", "economy", "member state", "nation", "economies", "area")):
                ent_col = c
                break
        if ent_col is None:
            best_c, best_f = None, 0.0
            for c in range(ncols):
                if c == year_col or c == ind_col or is_skip(c):
                    continue
                if nfracs[c] > 0.5 or year_of(headers[c]) is not None:
                    continue
                score = sfracs[c]
                if headers[c].lower() in ("entity", "name", "label"):
                    score = 1.0
                if score > best_f:
                    best_c, best_f = c, score
            if best_c is not None and best_f >= key_frac and uniq[best_c] >= 2:
                ent_col = best_c

    val_col = None
    if ind_col is not None:
        for c in range(ncols):
            if c in (year_col, ind_col, ent_col) or is_skip(c):
                continue
            if headers[c].lower() in ("value", "values", "amount", "observation", "obs_value", "data"):
                val_col = c
                break
        if val_col is None:
            numeric_only = [c for c in range(ncols) if c not in (year_col, ind_col, ent_col) and not is_skip(c) and nfracs[c] >= 0.55 and header_years[c] is None]
            if len(numeric_only) == 1:
                val_col = numeric_only[0]

    numeric_cols = []
    for c in range(ncols):
        if c in (year_col, ind_col, ent_col, val_col) or is_skip(c):
            continue
        if header_years[c] is not None:
            continue
        if nfracs[c] >= 0.55 and sfracs[c] < 0.5:
            numeric_cols.append(c)

    metric_base = re.sub(r"[\s_]+", " ", os.path.splitext(t.get("source", ""))[0]).strip() or "value"

    if ind_col is not None and val_col is not None:
        for r in rows:
            metric = clean_header(r[ind_col]) if r[ind_col] is not None else metric_base
            entity = clean_header(r[ent_col]) if (ent_col is not None and r[ent_col] is not None) else None
            y = year_of(r[year_col]) if year_col is not None else None
            v = parse_number(r[val_col]) if val_col < len(r) else None
            if v is not None or y is not None:
                out.append({"metric": metric, "entity": entity, "pts": [(y, v)], "src": t.get("source", "")})
        return

    if numeric_cols:
        for c in numeric_cols:
            name = clean_header(headers[c]) or metric_base
            for r in rows:
                y = year_of(r[year_col]) if year_col is not None else None
                v = parse_number(r[c])
                if v is not None:
                    out.append({"metric": name, "entity": clean_header(r[ent_col]) if (ent_col is not None and r[ent_col] is not None) else None,
                                "pts": [(y, v)], "src": t.get("source", "")})
        return

    if ent_col is not None:
        name = metric_base
        for r in rows:
            v = parse_number(r[0]) if r and headers[0].lower() not in SKIP_HEADERS else None
            # fall back: pick the numeric cell
            if v is None:
                for c in range(ncols):
                    v = parse_number(r[c])
                    if v is not None:
                        break
            y = year_of(r[year_col]) if year_col is not None else None
            if v is not None:
                out.append({"metric": name, "entity": clean_header(r[ent_col]) if r[ent_col] is not None else None,
                            "pts": [(y, v)], "src": t.get("source", "")})
        return

    # single unnamed numeric series
    for c in range(ncols):
        if nfracs[c] > 0.4 and c != year_col:
            for r in rows:
                y = year_of(r[year_col]) if year_col is not None else None
                v = parse_number(r[c])
                if v is not None:
                    out.append({"metric": metric_base, "entity": None, "pts": [(y, v)], "src": t.get("source", "")})
            return


def discover_files(root):
    found = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS and not d.startswith(".")]
        for fn in sorted(filenames):
            full = os.path.join(dirpath, fn)
            if fn == os.path.basename(sys.argv[0]) or os.path.abspath(full) == os.path.abspath(REPORT_PATH):
                continue
            ext = os.path.splitext(fn)[1].lower()
            if ext in (".csv", ".tsv", ".txt", ".dat", ".json", ".md", ".markdown"):
                found.append(full)
    return found


def pick_series(recs):
    # merge records with identical (family, name-key, entity) and take the longest per (family, entity)
    merged = {}
    for rec in recs:
        key = (classify(rec["metric"]), str(rec["metric"]).lower(), (rec["entity"] or "").lower())
        pts = norm_pts(rec["pts"])
        if not pts:
            continue
        if key not in merged:
            merged[key] = {"family": classify(rec["metric"]), "name": rec["metric"],
                           "entity": rec["entity"], "src": rec["src"], "pts": pts}
        else:
            # merge same-name series points
            existing = merged[key]
            comb = existing["pts"] + pts
            merged[key]["pts"] = norm_pts(comb)
    by_fam_ent = {}
    for key, rec in merged.items():
        fam = rec["family"]
        ent = (rec["entity"] or "").lower()
        cur = by_fam_ent.get((fam, ent))
        if cur is None or len(rec["pts"]) > len(cur["pts"]):
            by_fam_ent[(fam, ent)] = rec
    return list(by_fam_ent.values())


def eu_series(series, family):
    """Europe-wide series: official aggregate if present, else simple average/aggregate of economies."""
    aggs = [s for s in series if s["family"] == family and is_aggregate_entity(s["entity"]) and len(s["pts"]) >= 2]
    if aggs:
        s = max(aggs, key=lambda x: len(x["pts"]))
        return s["pts"], s["name"] + " (aggregate)", s["src"]
    ents = [s for s in series if s["family"] == family and s["entity"] and not is_aggregate_entity(s["entity"]) and len(s["pts"]) >= 2]
    if len(ents) >= 3:
        years = sorted({y for s in ents for y, _ in s["pts"] if isinstance(y, int)})
        pts = []
        for y in years:
            vals = [v for s in ents for yy, v in s["pts"] if yy == y]
            if len(vals) >= max(2, int(0.4 * len(ents))):
                if family == "gdp":
                    pts.append((y, sum(vals)))
                else:
                    pts.append((y, statistics.mean(vals)))
        if pts:
            return pts, f"Europe simple average of {len(ents)} reporting economies", None
    return [], None, None


def fmt_num(v, pct=False, signed=False):
    if v is None:
        return "n/a"
    dp = 1
    if abs(v) < 1 and v != 0:
        dp = 2
    if abs(v) >= 1000 and not pct:
        s = f"{v:,.0f}"
    else:
        s = f"{v:.{dp}f}"
    if pct:
        s = s + "%"
    if signed and v > 0:
        s = "+" + s
    return s


def summary(pts):
    if not pts:
        return None
    n = len(pts)
    first_y, first_v = pts[0]
    last_y, last_v = pts[-1]
    prev_y, prev_v = pts[-2] if n >= 2 else (None, None)
    vals = [v for _, v in pts]
    net = last_v - first_v
    return {"n": n, "first_y": first_y, "first_v": first_v, "last_y": last_y, "last_v": last_v,
            "prev_y": prev_y, "prev_v": prev_v, "net": net, "min": min(vals), "max": max(vals),
            "min_y": pts[vals.index(min(vals))][0], "max_y": pts[vals.index(max(vals))][0]}


def spark(pts, width=10):
    pts = pts[-width:]
    vals = [v for _, v in pts]
    lo, hi = min(vals), max(vals)
    if hi - lo < 1e-12:
        return "▄" * len(vals)
    return "".join(SPARK[min(7, max(0, int(round((v - lo) / (hi - lo) * 7))))] for v in vals)


def bar(vals_dict, width=22):
    items = [(k, v) for k, v in vals_dict.items() if v is not None]
    if not items:
        return []
    mx = max(abs(v) for _, v in items) or 1.0
    lines = []
    for k, v in sorted(items, key=lambda kv: kv[1], reverse=True):
        ln = int(round(abs(v) / mx * width))
        arrow = "▲" if v > 0 else ("▼" if v < 0 else "•")
        lines.append((k, v, arrow, "█" * ln))
    return lines


def pearson(xs, ys):
    if len(xs) < 4 or len(xs) != len(ys):
        return None
    try:
        r = statistics.correlation(xs, ys)
        return r if math.isfinite(r) else None
    except Exception:
        return None


def latest_cross(series, family):
    rows = []
    for s in series:
        if s["family"] != family or not s["entity"] or is_aggregate_entity(s["entity"]):
            continue
        if len(s["pts"]) < 2:
            continue
        y, v = s["pts"][-1]
        prev = None
        if len(s["pts"]) >= 2:
            prev = s["pts"][-2][1]
        rows.append({"name": s["entity"], "last": v, "last_y": y, "prev": prev, "pts": s["pts"]})
    return rows


def trend_phrase(family, net):
    eps = 1e-9
    if abs(net) < eps:
        return "broadly flat"
    if family in ("gdp_growth", "gdp"):
        return "expanding" if net > 0 else "contracting"
    if family == "inflation":
        return "rising prices" if net > 0 else "disinflation"
    if family in ("unemployment",):
        return "tightening labour market (unemployment down)" if net < 0 else "softening labour market (unemployment up)"
    if family == "employment":
        return "more people in work" if net > 0 else "fewer people in work"
    if family == "deficit":
        return "improving fiscal balance" if net > 0 else "widening fiscal deficit"
    if family == "debt":
        return "deleveraging" if net < 0 else "rising debt"
    return "rising" if net > 0 else "falling"


# ----------------------------------------------------------------------------
def main():
    files = discover_files(SEARCH_ROOT)
    recs = []
    file_report = []
    for path in files:
        try:
            tables = load_tables(path)
        except Exception as exc:  # noqa: BLE001
            print(f"[warn] could not parse {path}: {exc}")
            continue
        nrows = 0
        for t in tables:
            nrows += len(t.get("rows") or [])
            process_table(t, recs)
        if tables:
            file_report.append({"file": os.path.relpath(path, BASE), "tables": len(tables), "rows": nrows})
    series = pick_series(recs)

    fams = sorted({s["family"] for s in series})
    ents = sorted({s["entity"] for s in series if s["entity"] and not is_aggregate_entity(s["entity"])})
    aggs = sorted({s["entity"] for s in series if s["entity"] and is_aggregate_entity(s["entity"])})
    years_all = [y for s in series for y, _ in s["pts"] if isinstance(y, int)]
    period = (min(years_all), max(years_all)) if years_all else (None, None)

    fam_order = ["gdp_growth", "inflation", "unemployment", "gdp", "debt", "deficit",
                 "employment", "productivity", "investment", "exports", "imports", "trade_balance"]
    fams_present = [f for f in fam_order if f in fams] + [f for f in sorted(fams) if f not in fam_order and f != "other"] + (["other"] if "other" in fams else [])

    eu = {}
    eu_label = {}
    for f in fams_present:
        pts, label, src = eu_series(series, f)
        if pts:
            eu[f] = pts
            eu_label[f] = (label, src)

    out = []
    A = out.append
    A(f"# European Economic Performance — A Data Story")
    A("")
    A(f"*Prepared {datetime.now(timezone.utc).strftime('%d %b %Y %H:%M')} UTC from the data files in this workspace "
      f"(`{os.path.relpath(SEARCH_ROOT, BASE) or '.'}`). Methods and caveats at the end.*")
    A("")

    if not series:
        A("## What happened when we looked for the data")
        A("")
        A("No machine-readable numeric series describing European economic performance were found in the workspace. "
          "Discovered candidate files (if any) could not be parsed into year/indicator series.")
        for fr in file_report:
            A(f"- `{fr['file']}` — {fr['tables']} table(s), {fr['rows']} row(s), no usable numeric series")
        A("")
        A("**Next step:** provide the data as CSV/TSV/JSON (one file per indicator with country × year, "
          "or a long table with columns such as *country, year, indicator, value*) and rerun this analysis.")
        with open(REPORT_PATH, "w", encoding="utf-8") as fh:
            fh.write("\n".join(out) + "\n")
        print(f"Wrote {REPORT_PATH} (no usable numeric data found; {len(files)} candidate file(s) scanned).")
        return

    # ------------------------------------------------------------------ HEADLINE
    headline_fam = next((f for f in fam_order if f in eu), fams_present[0] if fams_present else None)
    A("## The headline")
    A("")
    if headline_fam and headline_fam in eu:
        s = summary(eu[headline_fam])
        label, src = eu_label[headline_fam]
        pct = headline_fam in PERCENT_FAMILIES
        if s:
            hline = (f"**{FAMILY_LABEL[headline_fam]}** moved from **{fmt_num(s['first_v'], pct)}** ({s['first_y']}) "
                     f"to **{fmt_num(s['last_v'], pct)}** ({s['last_y']}) — {fmt_num(s['net'], pct, signed=True)} over the period, "
                     f"i.e. the European economy is now **{trend_phrase(headline_fam, s['net'])}**.")
            A(hline)
            A("")
            if s["prev_v"] is not None:
                A(f"Looking at the most recent step only, the reading went from {fmt_num(s['prev_v'], pct)} ({s['prev_y']}) "
                  f"to {fmt_num(s['last_v'], pct)} ({s['last_y']}), a year-on-year move of "
                  f"{fmt_num(s['last_v'] - s['prev_v'], pct, signed=True)}.")
                A("")
            A(f"The series used for this headline is *{label}* (`{src or 'derived from country data'}`), "
              f"covering {s['n']} time points between {s['first_y']} and {s['last_y']}.")
    else:
        A("**Headline series unavailable** — the tables found contain country/indicator readings but no Europe-wide aggregate "
          "could be formed; country-level findings below are computed directly from the discovered files.")
    A("")
    A("## The setup: what the data covers")
    A("")
    A(f"- **Period observed:** {period[0]}–{period[1]}" if period[0] else "- **Period observed:** not clearly dated")
    A(f"- **Reporting economies:** {len(ents)} (incl. e.g. {', '.join(ents[:6])}{' …' if len(ents) > 6 else ''})" if ents else "- **Reporting economies:** none identified separately")
    A(f"- **Aggregate blocs recognised in the data:** {', '.join(aggs[:6])}{' …' if len(aggs) > 6 else ''}" if aggs else "- **Aggregate blocs:** none labelled (EU/euro-area)")
    A(f"- **Indicator families found:** {', '.join(FAMILY_LABEL.get(f, f) for f in fams_present)}")
    A(f"- **Data sources parsed:** {len(file_report)} file(s)")
    for fr in file_report:
        A(f"  - `{fr['file']}` — {fr['tables']} table(s), {fr['rows']} data row(s)")
    A("")
    A("## The trend: key indicators, Europe-wide")
    A("")
    A("The table below shows the Europe-wide series reconstructed for each indicator family "
      "(an official aggregate when present, otherwise the simple average across reporting economies).")
    A("")
    A("| Indicator | First | Latest | Previous | Net change | Trend (sparkline) |")
    A("|---|---:|---:|---:|---:|:---:|")
    for f in fams_present:
        if f not in eu:
            continue
        s = summary(eu[f])
        if not s or s["n"] < 2:
            continue
        pct = f in PERCENT_FAMILIES
        net_s = fmt_num(s["net"], pct, signed=True) if f != "other" else f"Δ {fmt_num(s['net'])}"
        A(f"| {FAMILY_LABEL.get(f, f)} | {fmt_num(s['first_v'], pct)} ({s['first_y']}) | **{fmt_num(s['last_v'], pct)}** ({s['last_y']}) "
          f"| {fmt_num(s['prev_v'], pct)} ({s['prev_y']}) | {net_s} | `{spark(eu[f])}` |")
    A("")
    if "gdp_growth" in eu:
        s = summary(eu["gdp_growth"])
        if s:
            A(f"**Reading the trend line:** growth peaked at {fmt_num(s['max'], True)} ({s['max_y']}) and bottomed at "
              f"{fmt_num(s['min'], True)} ({s['min_y']}). The arc from start to finish is {fmt_num(s['net'], True, signed=True)}.")
            A("")

    # -------------------------------------------------------------- CONTRAST / COUNTRIES
    sel_fams = [f for f in ["gdp_growth", "inflation", "unemployment", "gdp", "debt", "deficit"] if len(latest_cross(series, f)) >= 4]
    if not sel_fams:
        sel_fams = [f for f in fams_present if len(latest_cross(series, f)) >= 4]
    if sel_fams:
        A("## Rising action: how the economies compare")
        A("")
        for f in sel_fams[:3]:
            rows = latest_cross(series, f)
            rows.sort(key=lambda r: (r["last"] is None, r["last"]), reverse=True)
            pct = f in PERCENT_FAMILIES
            A(f"### {FAMILY_LABEL.get(f, f)} — latest cross-section")
            A("")
            A("| Economy | Latest | Previous | YoY | Sparkline (last 8) |")
            A("|---|---:|---:|---:|:---:|")
            for r in rows:
                dy = ""
                if r["prev"] is not None and r["last"] is not None:
                    dy = fmt_num(r["last"] - r["prev"], pct, signed=True)
                A(f"| {r['name']} | {fmt_num(r['last'], pct)} ({r['last_y']}) | {fmt_num(r['prev'], pct)} | {dy} | `{spark(r['pts'], 8)}` |")
            A("")
            top = rows[:3]
            bottom = rows[-3:] if len(rows) >= 3 else []
            lead = f"**Leaders:** {', '.join(f'{r[\"name\"]} ({fmt_num(r[\"last\"], pct)})' for r in top)}."
            lag = f" **Trailing:** {', '.join(f'{r[\"name\"]} ({fmt_num(r[\"last\"], pct)})' for r in bottom)}." if bottom else ""
            A(lead + lag)
            A("")
            A("```")
            A(f"Scale: relative position, {FAMILY_LABEL.get(f, f).lower()}")
            for k, v, arrow, bar_ch in bar({r["name"]: r["last"] for r in rows}):
                A(f"{k:<22} {arrow} {bar_ch:<22} {fmt_num(v, pct)}")
            A("```")
            A("")

        A("## The insight: where the action really is")
        A("")
        for f in sel_fams[:3]:
            rows = latest_cross(series, f)
            if not rows:
                continue
            movers = []
            for r in rows:
                if r["prev"] is not None and r["last"] is not None:
                    movers.append((r["name"], r["last"] - r["prev"], r["last_y"]))
            if not movers:
                continue
            pct = f in PERCENT_FAMILIES
            movers.sort(key=lambda x: x[1], reverse=True)
            up = movers[0]
            down = movers[-1]
            improved = sum(1 for _, d, _ in movers if d > 0)
            A(f"- **{FAMILY_LABEL.get(f, f)}:** biggest year-on-year rise **{up[0]}** ({fmt_num(up[1], pct, signed=True)} to {up[2]}); "
              f"biggest fall **{down[0]}** ({fmt_num(down[1], pct, signed=True)}). Breadth: {improved} of {len(movers)} economies improved.")
        A("")
        cross = {}
        for a, b in (("gdp_growth", "inflation"), ("inflation", "unemployment")):
            ra = latest_cross(series, a)
            rb = latest_cross(series, b)
            da = {r["name"]: r["last"] for r in ra}
            db = {r["name"]: r["last"] for r in rb}
            common = [(da[k], db[k]) for k in da if k in db]
            if len(common) >= 5:
                rv = pearson([x[0] for x in common], [x[1] for x in common])
                if rv is not None:
                    cross[(a, b)] = (rv, len(common))
        if cross:
            for (a, b), (rv, n) in cross.items():
                sense = "moves together with" if rv > 0 else "moves against"
                A(f"- **Pattern check:** across {n} economies, {FAMILY_LABEL.get(a, a).lower()} {sense} "
                  f"{FAMILY_LABEL.get(b, b).lower()} at the latest observation (correlation {rv:+.2f}). "
                  f"Correlation is descriptive, not causal.")
            A("")
        A("## Resolution: what the story suggests")
        A("")
        A("Putting the three pillars together — the numbers, the narrative, and the comparisons above:")
        A("")
        A("1. **A single European headline can mislead.** The gap between leaders and trailing economies is visible in every "
          "indicator family; policies and outlooks differ more inside Europe than the Europe-wide average suggests.")
        A("2. **The latest year-on-year step matters as much as the long arc.** Watch the economies flagged as the largest "
          "movers: they define where the next average reading is headed.")
        A("3. **Cross-indicator tension is the story to manage.** Where inflation and growth pull apart, or unemployment and "
          "prices move in the same direction, decision-makers face trade-offs rather than one-size-fits-all answers.")
        A("")
        A("### Suggested focus areas (derived from the data, for stakeholder discussion)")
        A("")
        A(f"- Monitor the **{sel_fams[0] if sel_fams else ''}** leaders and laggards each quarter to test whether dispersion narrows or widens.")
