        A("")

    # --------------------------------------------------------------------- visual recap
    A("## One-glance visual recap")
    A("")
    if "gdp_growth" in eu:
        s = summary(eu["gdp_growth"])
        if s:
            A("```")
            A(f"Europe-wide real GDP growth   ({s['first_y']} → {s['last_y']})")
            A(f"  {''.join(SPARK[min(7, max(0, int(round((v - s['min']) / max(1e-9, s['max'] - s['min']) * 7))))] for _, v in eu['gdp_growth'])}")
            A(f"  low {fmt_num(s['min'], True)} ({s['min_y']})   high {fmt_num(s['max'], True)} ({s['max_y']})   latest {fmt_num(s['last_v'], True)}")
            A("```")
            A("")
    for f in sel_fams[:2] if sel_fams else []:
        rows = latest_cross(series, f)
        if not rows:
            continue
        pct = f in PERCENT_FAMILIES
        A("```")
        A(f"Latest {FAMILY_LABEL.get(f, f).lower()} by economy (indexed bars)")
        items = [(r["name"], r["last"]) for r in rows]
        mx = max((abs(v) for _, v in items if v is not None), default=1) or 1
        for k, v in sorted(items, key=lambda kv: (kv[1] is None, kv[1]), reverse=True)[:8]:
            if v is None:
                continue
            width = max(1, int(round(abs(v) / mx * 26)))
            A(f"{k:<22} {'█' * width} {fmt_num(v, pct)}")
        A("```")
        A("")

    # ---------------------------------------------------------------------- caveats
    A("## Caveats and how to read this")
    A("")
    A("- All figures are computed directly from the files listed under *Setup*; no outside data was assumed. "
      "Values with non-numeric or missing cells were skipped for the affected year only.")
    A("- \"Europe-wide\" series use an official aggregate (e.g. EU/euro-area) when present in the files, otherwise a "
      "transparent simple average of the reporting economies; the label used is shown in the Headline section.")
    A("- Units differ across indicators (%, index levels, currency amounts). Percent-style families are marked with `%`; "
      "levels are shown as recorded in the source and are not re-based.")
    A("- Year-on-year (YoY) here means the change between the two most recent available observations for that economy; "
      "if a country reports with a lag, its YoY reflects its own last two data points.")
    A("- Correlations are descriptive cross-sectional statistics over a single period and should not be read as causal.")
    A("")
    A("## Methodology")
    A("")
    A("1. Scanned the workspace (`" + os.path.relpath(SEARCH_ROOT, BASE) + "`) for CSV/TSV/TXT/DAT/JSON/Markdown files.")
    A("2. Parsed tables and detected three column roles automatically: **time** (year column or year column headers), "
      "**entity** (economy/region), and **measure** (indicator/value columns).")
    A("3. Classified each measure into an indicator family (GDP, growth, inflation, unemployment, debt, deficit, trade, …).")
    A("4. Reconstructed per-economy time series (missing values dropped per year; duplicate years averaged).")
    A("5. Computed the Europe-wide trend, the latest cross-section per family, leader/trailer tables, year-on-year movers, "
      "and cross-indicator correlations, then rendered this markdown report.")
    A("")
    A("---")
    A(f"*Report generated by `{os.path.basename(sys.argv[0])}` — {len(files)} candidate file(s) scanned, "
      f"{len(series)} usable indicator series, {len(ents)} economies, {len(aggs)} aggregate bloc(s).*")

    with open(REPORT_PATH, "w", encoding="utf-8") as fh:
        fh.write("\n".join(out) + "\n")

    print(f"Report written: {REPORT_PATH}")
    print(f"Files scanned: {len(files)}")
    for fr in file_report:
        print(f"  - {fr['file']}: {fr['tables']} table(s), {fr['rows']} rows")
    print(f"Usable indicator series: {len(series)}")
    print("Indicator families present: " + ", ".join(FAMILY_LABEL.get(f, f) for f in fams_present))
    print(f"Economies: {len(ents)} | Aggregates: {len(aggs)} | Period: {period[0]}–{period[1]}")
    for f in fams_present:
        if f in eu:
            print(f"  Europe series [{f}]: {len(eu[f])} points -> {eu_label[f][0]}")


if __name__ == "__main__":
    main()

