#!/usr/bin/env python3
"""Task-scoped helper: inventory the workspace and preview candidate data files
for the European economic performance data storytelling report."""
import os
import json
import sys

root = os.getcwd()
print("CWD:", root)

def safe_preview(path, limit_lines=12, limit_chars=600):
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            head = []
            for _ in range(limit_lines):
                line = fh.readline()
                if not line:
                    break
                head.append(line)
        text = "".join(head)
        return text[:limit_chars]
    except Exception as exc:  # pragma: no cover - diagnostic only
        return f"<preview failed: {exc}>"

text_ext = {".csv", ".tsv", ".txt", ".json", ".md", ".log", ".xml", ".html"}

for dirpath, dirnames, filenames in os.walk(root):
    # skip hidden / venv style directories for tidiness
    dirnames[:] = [d for d in dirnames if not d.startswith(".") and d not in ("__pycache__", "venv", ".venv")]
    for name in sorted(filenames):
        full = os.path.join(dirpath, name)
        try:
            size = os.path.getsize(full)
        except OSError:
            size = -1
        rel = os.path.relpath(full, root)
        print("-" * 70)
        print(f"FILE: {rel}  ({size} bytes)")
        ext = os.path.splitext(name)[1].lower()
        if ext in text_ext and size <= 5_000_000:
            print(safe_preview(full))
        elif ext in text_ext:
            print(f"(file larger than preview limit; ext={ext})")
        else:
            print(f"(non-text extension: {ext or '<none>'})")
print("-" * 70)
print("Inventory complete.")
